"""Source-verified additions prompted by the user-shared Gemini topic guide.
Original wording and scenarios; third-party reproduced questions are not imported.
"""
AWS='https://docs.aws.amazon.com/'
def enrich(packs,question,lesson):
 p=packs[2];bank=p['questions']
 def add(d,prompt,c,w,why,path,hint):bank.append(question(len(bank)+1,d,prompt,c,w,why,AWS+path,hint))
 add(3,'A team already has an agent built with an open-source framework. It needs managed hosting with isolated execution sessions. Which AgentCore component fits?','AgentCore Runtime',[('AgentCore Memory','Memory retains interaction context rather than hosts the executing agent.'),('An S3 vector index alone','A vector index does not execute an agent.'),('Model Registry alone','A model catalogue is not an agent runtime.')],'Runtime provides a managed execution environment for agents and tools, with session isolation. Configure identity, network access and tool permissions separately.','bedrock-agentcore/latest/devguide/runtime-sessions.html','Separate hosting the agent from remembering its conversations.')
 add(3,'An agent must discover and invoke existing business APIs and Lambda functions through MCP-compatible tools. Which component is directly relevant?','AgentCore Gateway',[('AgentCore Memory','Memory is about retained context, not converting APIs into tools.'),('SageMaker Model Monitor','Model Monitor evaluates inference data and quality, not tool integration.'),('A CSV file format','File serialization does not provide an agent tool endpoint.')],'Gateway can expose supported APIs and services as tools through a managed gateway. Authentication and resource authorization still need explicit configuration.','bedrock-agentcore/latest/devguide/gateway.html','Which component connects agents with callable tools?')
 add(3,'An assistant should retain a user’s delivery preferences across separate conversations. Which AgentCore capability is the closest fit?','Long-term AgentCore Memory',[('Only a single request context window','A single request context does not automatically persist across sessions.'),('An endpoint auto-scaling target','Scaling targets control capacity, not retained user context.'),('A model training learning rate','A learning rate does not store a user preference for later sessions.')],'Long-term memory retains selected information across sessions. Scope access, retention and user identity so one person’s context is not exposed to another.','bedrock-agentcore/latest/devguide/memory.html','Does the information need to outlive one conversation?')
 add(4,'An agent must access a third-party service on behalf of an authenticated user without putting their credentials into the prompt. Which component helps manage that identity and credentials?','AgentCore Identity',[('A higher sampling temperature','Sampling randomness does not handle credentials.'),('A larger embedding dimension','Vector size does not implement authentication.'),('A public S3 object containing tokens','Public token storage exposes credentials rather than protecting them.')],'AgentCore Identity supports agent authentication and credential management. Keep authorization enforced in the execution path and avoid placing secrets in prompts or logs.','bedrock-agentcore/latest/devguide/identity.html','Which service is responsible for authentication and credential handling?')
 add(3,'A data-analysis agent needs to execute generated Python in an isolated managed sandbox. Which tool is purpose-built for this?','AgentCore Code Interpreter',[('A vector database alone','Vector retrieval does not execute Python.'),('CloudTrail alone','CloudTrail audits supported API activity rather than runs code.'),('Prompt Management alone','Prompt versioning does not supply a code execution sandbox.')],'Code Interpreter runs generated code in a managed sandbox. Configure allowed data access, session settings and network behavior for the workload.','bedrock-agentcore/latest/devguide/code-interpreter-tool.html','Which capability runs code rather than retrieves text or versions prompts?')
 add(1,'A pipeline prepares training input for SageMaker’s built-in DeepAR forecasting algorithm. Which pair of formats is supported?','JSON Lines or Parquet',[('Only image/jpeg','Image serialization is not the DeepAR training data format.'),('Only a model registry package ARN','An artifact reference is not a serialized training dataset.'),('Only an OpenAPI schema','An API specification is not a DeepAR training dataset.')],'DeepAR supports JSON Lines or Parquet training datasets. Use the schema and time-series representation required by the algorithm.','sagemaker/latest/dg/deepar.html','Check the selected algorithm’s training contract, not a generic file preference.')
 add(1,'A recommendation pipeline uses SageMaker’s built-in Factorization Machines algorithm in Pipe mode. Which training serialization fits?','recordIO-protobuf',[('Only unstructured prose','The algorithm requires its supported numeric record representation.'),('Only JPEG images','This algorithm is not receiving image classification input.'),('Only a JSON inference response','Inference output serialization is a different contract from training input.')],'The built-in algorithm supports recordIO-protobuf for training in File or Pipe mode. Do not infer the training contract from supported prediction-response formats.','sagemaker/latest/dg/common-info-all-im-models.html','Distinguish training data from inference request and response formats.')
 add(2,'A generated summary has high word overlap with a reference but includes an unsupported financial claim. Which conclusion is justified?','Overlap metrics alone do not establish factual faithfulness',[('High overlap proves every claim is correct','Surface similarity cannot guarantee grounding of all claims.'),('Longer output always improves factual correctness','Length does not establish truth.'),('A faster endpoint proves stronger summary quality','Latency measures response speed, not faithfulness.')],'ROUGE-style overlap can be useful, but evaluate whether claims are supported by source evidence using a suitable rubric and human review where needed.','sagemaker/latest/dg/autopilot-llms-finetuning-metrics.html','Does the metric actually verify each factual claim?')
 add(2,'Relevant passages appear in the retrieved candidate set, but the strongest evidence is ranked below less relevant chunks. Which retrieval-stage change should be tested?','Rerank candidate passages for relevance',[('Always fine-tune the generation model first','The diagnosed failure is candidate ordering before generation.'),('Remove the relevant passages','That removes the evidence needed to answer.'),('Replace IAM with a longer context window','Authorization is unrelated to relevance ranking.')],'A reranker can reorder retrieved candidates by relevance. Measure retrieval and downstream answer quality rather than assuming improvement.','bedrock/latest/userguide/rerank.html','Was evidence absent entirely, or present but poorly ordered?')
 add(4,'A new model release triggers input-quality alarms. What is the most responsible response before changing its monitoring baseline?','Investigate the alarms and approve a new baseline only if the expected data legitimately changed',[('Always baseline the latest traffic to silence alarms','This can normalize corrupted data or a real production failure.'),('Delete captured inputs immediately','This removes useful diagnostic evidence.'),('Assume the model update proves all alarms are false','A deployment does not establish that input data is valid.')],'Validate schema, preprocessing, capture configuration and real data changes. Update the monitoring baseline deliberately when representative validated data justifies it.','sagemaker/latest/dg/model-monitor-create-baseline.html','Could re-baselining hide the problem you need to detect?')
 p['freeIds']=[1,2,3,4,5,6,8,31,9,34]
 p['lessons'] += [lesson('Map AgentCore responsibilities','Runtime hosts agents; Gateway connects callable tools; Memory retains conversation context; Identity manages agent authentication and credentials; Code Interpreter executes generated code in a sandbox. These capabilities complement application authorization and audit controls.','Which component remembers preferences across sessions?','Long-term AgentCore Memory.','A service agent needs isolated hosting, API tools and durable user preferences. Map the components and a verification check.','Use Runtime, Gateway and Memory, with Identity where needed. Test session separation, resource authorization and user-scoped memory retrieval. Use traces to diagnose tool failures, and keep credentials out of prompts.'),lesson('Check formats and evaluation contracts','Training input, inference input and model output are different contracts. Check each selected algorithm’s supported formats. DeepAR accepts JSON Lines or Parquet training data; Factorization Machines uses recordIO-protobuf. Text overlap and semantic-similarity metrics complement factual and safety review.','Can supported inference JSON prove an algorithm accepts JSON training input?','No. Training and inference contracts must be checked separately.','A summary looks similar to its reference but invents a payment term. Propose an evaluation and correction workflow.','Use source-grounded factual assessment and human review for high-impact claims. Inspect retrieved evidence and prompts. Track unsupported claims separately from overlap, similarity, latency and token cost.')]
 p['references']=[
 dict(title='Choose an inference path',headers=['Requirement','Candidate','Check'],rows=[['Immediate interactive response','Real-time endpoint','Persistent capacity; verify payload, timeout and load'],['Intermittent lightweight traffic','Serverless inference','Cold-start tolerance and supported model features'],['Queued long processing','Asynchronous inference','Delayed output accepted; scale-to-zero configuration'],['Known dataset, results later','Batch Transform','Offline input/output contracts; no persistent endpoint']],source=AWS+'sagemaker/latest/dg/deploy-model-options.html'),
 dict(title='Choose how to adapt a foundation model',headers=['Need','Technique','Watch for'],rows=[['Improve task instructions','Prompt engineering','Test before introducing training complexity'],['Current private evidence','RAG','Freshness, access, retrieval and citations'],['Repeated response behavior','Fine-tuning','Representative examples and held-out evaluation'],['Broad domain adaptation','Continued pre-training','Supported models and prepared domain corpus'],['Smaller student model','Distillation','Quality, latency and cost trade-offs']],source=AWS+'bedrock/latest/userguide/model-customization.html'),
 dict(title='AgentCore component map',headers=['Responsibility','Component','Distinction'],rows=[['Run an agent','Runtime','Execution and session isolation'],['Expose callable APIs/tools','Gateway','Tool connectivity, not conversation storage'],['Keep interaction context','Memory','Short-term context versus cross-session knowledge'],['Manage credentials/identity','Identity','Authentication complements resource authorization'],['Run generated code','Code Interpreter','Sandbox settings and permitted access matter']],source=AWS+'bedrock-agentcore/latest/devguide/what-is-bedrock-agentcore.html'),
 dict(title='Training-format checkpoints',headers=['Algorithm','Training input','Trap'],rows=[['DeepAR forecasting','JSON Lines or Parquet','Do not assume every algorithm accepts CSV'],['Factorization Machines','recordIO-protobuf','Check training versus inference serialization'],['Any built-in algorithm','Its documented schema and modes','A file extension alone does not establish compatibility']],source=AWS+'sagemaker/latest/dg/common-info-all-im-models.html'),
 dict(title='Evaluate the right thing',headers=['Question','Measure','Limitation'],rows=[['How many actual positives were found?','Recall','Does not measure the cost of false positives'],['How many predicted positives were real?','Precision','Does not measure all missed positives'],['Overlap with reference wording?','BLEU / ROUGE','Not proof of factual correctness'],['Similarity in contextual meaning?','BERTScore / semantic similarity','Not proof every claim is supported'],['Faithful, safe, useful output?','Rubric, human review, validated model judge','Calibrate judges and review consequential decisions']],source=AWS+'aws-certification/latest/machine-learning-engineer-associate-02/machine-learning-engineer-associate-02-domain2.html')]
 p['glossary']=[
 ['RAG — Retrieval-Augmented Generation','Retrieve source evidence and provide it as generation context.','A policy assistant retrieves the current refund rule before answering.'],['FM — Foundation Model','A broadly pre-trained model adapted or prompted for downstream tasks.','Evaluate candidate FMs for quality, latency, safety and cost.'],['MCP — Model Context Protocol','A protocol for exposing tools and contextual resources to AI applications.','Gateway can expose supported business APIs as MCP-compatible tools.'],['CDC — Change Data Capture','Capture committed changes rather than repeatedly copying a full source.','A pipeline records inserts, updates and deletes for downstream preparation.'],['HITL — Human in the Loop','A defined human review or decision point within a workflow.','A reviewer resolves an uncertain high-impact model output.'],['CI/CD — Continuous Integration / Continuous Delivery','Automated checks and controlled delivery of versioned changes.','Validate a prompt/model release and roll back if acceptance metrics fail.'],['Epoch / step / batch','An epoch is a dataset pass; a step is a parameter update; a batch groups examples.','Convert a schedule expressed in epochs into the optimizer’s required update units.'],['Faithfulness','Whether generated claims are supported by the supplied evidence.','Check that a summary does not invent a financial term.'],['Drift','A monitored change in data, predictions or their relationship to outcomes.','Investigate shifted inputs without automatically normalizing a faulty pipeline.'],['Precision / recall','Precision checks predicted positives; recall checks actual positives.','Choose thresholds using the cost of missed events and false alarms.']]
 # Add recall cards for new lessons, while preserving stable indexes for existing cards.
 p['cards'] += [dict(front=l['recall'],back=l['answer']) for l in p['lessons'][-2:]]
